package library_book_service.cqrs;

import io.micrometer.core.instrument.Counter;
import io.micrometer.core.instrument.MeterRegistry;
import io.micrometer.core.instrument.Timer;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;
import org.springframework.stereotype.Component;

/**
 * Micrometer command/query/projection metrics for the CQRS domain.
 *
 * <p>Wired through {@link CqrsBus}, the single choke point every registered command/query dispatch
 * flows through -- counters stay consistent across every handler by construction. Auto-generated by
 * datrix-codegen-java. Do not edit manually.
 */
@Component
public class CqrsMetrics {

  private static final String COMMAND_TOTAL_METRIC = "cqrs.command.total";
  private static final String COMMAND_DURATION_METRIC = "cqrs.command.duration";
  private static final String QUERY_TOTAL_METRIC = "cqrs.query.total";
  private static final String QUERY_DURATION_METRIC = "cqrs.query.duration";
  private static final String PROJECTION_TOTAL_METRIC = "cqrs.projection.total";
  private static final String COMMAND_TAG = "command";
  private static final String QUERY_TAG = "query";
  private static final String PROJECTION_TAG = "projection";
  private static final String EVENT_TAG = "event";
  private static final String STATUS_TAG = "status";

  private final MeterRegistry registry;
  private final ConcurrentHashMap<String, Counter> commandCounters = new ConcurrentHashMap<>();
  private final ConcurrentHashMap<String, Timer> commandTimers = new ConcurrentHashMap<>();
  private final ConcurrentHashMap<String, Counter> queryCounters = new ConcurrentHashMap<>();
  private final ConcurrentHashMap<String, Timer> queryTimers = new ConcurrentHashMap<>();
  private final ConcurrentHashMap<String, Counter> projectionCounters = new ConcurrentHashMap<>();

  public CqrsMetrics(MeterRegistry registry) {
    this.registry = registry;
  }

  public void recordCommand(String commandName, String status, long elapsedNanos) {
    commandCounters
        .computeIfAbsent(
            commandName + ":" + status,
            k ->
                Counter.builder(COMMAND_TOTAL_METRIC)
                    .tag(COMMAND_TAG, commandName)
                    .tag(STATUS_TAG, status)
                    .register(registry))
        .increment();
    commandTimers
        .computeIfAbsent(
            commandName,
            k ->
                Timer.builder(COMMAND_DURATION_METRIC)
                    .tag(COMMAND_TAG, commandName)
                    .register(registry))
        .record(elapsedNanos, TimeUnit.NANOSECONDS);
  }

  public void recordQuery(String queryName, String status, long elapsedNanos) {
    queryCounters
        .computeIfAbsent(
            queryName + ":" + status,
            k ->
                Counter.builder(QUERY_TOTAL_METRIC)
                    .tag(QUERY_TAG, queryName)
                    .tag(STATUS_TAG, status)
                    .register(registry))
        .increment();
    queryTimers
        .computeIfAbsent(
            queryName,
            k -> Timer.builder(QUERY_DURATION_METRIC).tag(QUERY_TAG, queryName).register(registry))
        .record(elapsedNanos, TimeUnit.NANOSECONDS);
  }

  public void recordProjection(String projectionName, String eventName, String status) {
    projectionCounters
        .computeIfAbsent(
            projectionName + ":" + eventName + ":" + status,
            k ->
                Counter.builder(PROJECTION_TOTAL_METRIC)
                    .tag(PROJECTION_TAG, projectionName)
                    .tag(EVENT_TAG, eventName)
                    .tag(STATUS_TAG, status)
                    .register(registry))
        .increment();
  }
}
